import dev.gamersclt.batcaverna.nativeapp.LibraryStatus;
public class LibraryStatusTest {
 public static void main(String[] args){String[][] games={{"🏆 100% (Platina)","Platinados"},{"✅ Zerado","Zerados"},{"🎮 Em Progresso","Em progresso"},{"🎮 Jogando agora","Jogando agora"},{"📌 Backlog","Backlog"},{"⏳ Pretendo Jogar","Backlog"},{"🟦 Biblioteca Steam","Biblioteca Steam"},{"⌛ Wishlist","Wishlist"},{"⏸️ Pausado","Pausados"},{"❌ Abandonado","Abandonados"},{"🧪 Simulando","Outros"}};for(String[] row:games)check(row[1],LibraryStatus.group(row[0],false));String[][] media={{"📺 Assistindo","Assistindo"},{"🍿 Maratonando","Assistindo"},{"⏳ Para Assistir","Para assistir"},{"✅ Assistido","Assistidos"},{"❤️ Favorito","Favoritos"},{"⏸️ Pausado","Pausados"},{"❌ Abandonado","Abandonados"}};for(String[] row:media)check(row[1],LibraryStatus.group(row[0],true));check("Outros",LibraryStatus.group(null,false));if(!LibraryStatus.finished("🏆 100% (Platina)",false)||LibraryStatus.finished("📌 Backlog",false)||!LibraryStatus.finished("❤️ Favorito",true)||LibraryStatus.finished("📺 Assistindo",true))throw new AssertionError("Finalizados incorretos");System.out.println("LibraryStatus: 23 checks passed");}static void check(String expected,String actual){if(!expected.equals(actual))throw new AssertionError(expected+" != "+actual);}
}
